window.ScripturaLexicons.BDAG_PART_0159 = {"source":"BDAG","searchAnchorId":"bdag-search-anchor","entryAnchorId":"bdag-entry-anchor","rowsHtml":"<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-zemia-bdag\" data-source=\"BDAG\" data-search=\"ζημία, ας, ἡ substantivo feminino dano; prejuízo; perda; privação BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ζημία, ας, ἡ</td><td>substantivo feminino</td><td>dano; prejuízo; perda; privação</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-zemioo-bdag\" data-source=\"BDAG\" data-search=\"ζημιόω verbo sofrer prejuízo; perder; ser punido BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ζημιόω</td><td>verbo</td><td>sofrer prejuízo; perder; ser punido</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-zenas-bdag\" data-source=\"BDAG\" data-search=\"Ζηνᾶς, acusativo -ᾶν, ὁ nome próprio masculino Zenas BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">Ζηνᾶς, acusativo -ᾶν, ὁ</td><td>nome próprio masculino</td><td>Zenas</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-zenon-bdag\" data-source=\"BDAG\" data-search=\"Ζήνων, ωνος, ὁ nome próprio masculino Zenão BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">Ζήνων, ωνος, ὁ</td><td>nome próprio masculino</td><td>Zenão</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-zeteo-bdag\" data-source=\"BDAG\" data-search=\"ζητέω verbo buscar; procurar; investigar; desejar; exigir BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ζητέω</td><td>verbo</td><td>buscar; procurar; investigar; desejar; exigir</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-zetema-bdag\" data-source=\"BDAG\" data-search=\"ζήτημα, ατος, τό substantivo neutro questão; assunto controverso; discussão BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ζήτημα, ατος, τό</td><td>substantivo neutro</td><td>questão; assunto controverso; discussão</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-zetesis-bdag\" data-source=\"BDAG\" data-search=\"ζήτησις, εως, ἡ substantivo feminino investigação; questão controversa; discussão BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ζήτησις, εως, ἡ</td><td>substantivo feminino</td><td>investigação; questão controversa; discussão</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-zizanion-bdag\" data-source=\"BDAG\" data-search=\"ζιζάνιον, ου, τό substantivo neutro joio; erva daninha BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ζιζάνιον, ου, τό</td><td>substantivo neutro</td><td>joio; erva daninha</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-zmyrna-bdag\" data-source=\"BDAG\" data-search=\"Ζμύρνα nome próprio feminino; variante textual Esmirna (variante) BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">Ζμύρνα</td><td>nome próprio feminino; variante textual</td><td>Esmirna (variante)</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-zorobabel-bdag\" data-source=\"BDAG\" data-search=\"Ζοροβαβέλ, ὁ nome próprio masculino indeclinável Zorobabel BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">Ζοροβαβέλ, ὁ</td><td>nome próprio masculino indeclinável</td><td>Zorobabel</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-zophos-bdag\" data-source=\"BDAG\" data-search=\"ζόφος, ου, ὁ substantivo masculino escuridão; trevas; regiões tenebrosas BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ζόφος, ου, ὁ</td><td>substantivo masculino</td><td>escuridão; trevas; regiões tenebrosas</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-zygos-bdag\" data-source=\"BDAG\" data-search=\"ζυγός, οῦ, ὁ substantivo masculino jugo; canga; balança BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ζυγός, οῦ, ὁ</td><td>substantivo masculino</td><td>jugo; canga; balança</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-zyme-bdag\" data-source=\"BDAG\" data-search=\"ζύμη, ης, ἡ substantivo feminino fermento; massa fermentada BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ζύμη, ης, ἡ</td><td>substantivo feminino</td><td>fermento; massa fermentada</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-zymoo-bdag\" data-source=\"BDAG\" data-search=\"ζυμόω verbo fermentar; levedar BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ζυμόω</td><td>verbo</td><td>fermentar; levedar</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-zo-bdag\" data-source=\"BDAG\" data-search=\"ζῶ verbo remissivo ver [ζάω] ζῶ BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ζῶ</td><td>verbo remissivo</td><td>ver [ζάω] ζῶ</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-zogreo-bdag\" data-source=\"BDAG\" data-search=\"ζωγρέω verbo capturar vivo; preservar vivo; ganhar pessoas BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ζωγρέω</td><td>verbo</td><td>capturar vivo; preservar vivo; ganhar pessoas</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-zoe-bdag\" data-source=\"BDAG\" data-search=\"ζωή, ῆς, ἡ substantivo feminino vida; existência; sustento; vida eterna BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ζωή, ῆς, ἡ</td><td>substantivo feminino</td><td>vida; existência; sustento; vida eterna</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-zone-bdag\" data-source=\"BDAG\" data-search=\"ζώνη, ης, ἡ substantivo feminino cinto; cinturão BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ζώνη, ης, ἡ</td><td>substantivo feminino</td><td>cinto; cinturão</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-zonnymi-bdag\" data-source=\"BDAG\" data-search=\"ζώννυμι verbo cingir; pôr cinto BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ζώννυμι</td><td>verbo</td><td>cingir; pôr cinto</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-zoogoneo-bdag\" data-source=\"BDAG\" data-search=\"ζωογονέω verbo dar vida; manter vivo BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ζωογονέω</td><td>verbo</td><td>dar vida; manter vivo</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n","cardsHtml":"<article id=\"entry-zemia-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ζημία, ας, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">(Epicarmo 148 [dórico <span class=\"greek\">ζαμία</span>]; Sófocles, Heródoto e outros; empréstimo no vocabulário rabínico. Em Heródoto, Tucídides e outros, geralmente «punição»). Em nossa literatura, refere-se apenas a sofrer a perda de alguma coisa, com a implicação de passar por dificuldades ou sofrimentos: <strong>dano, desvantagem, perda, privação</strong> (Fílon, Somn. 1, 124 e outros; Josefo, Ant. 4, 211), Hs 6, 3, 4. <span class=\"greek\">μετὰ</span> <span class=\"greek\">πολλῆς</span> <span class=\"greek\">ζ</span>. <span class=\"greek\">τινός</span>, «com grande perda de alguma coisa», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.27.10\" target=\"_blank\" rel=\"noopener noreferrer\">At 27:10</a>; <span class=\"greek\">κερδῆσαι</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">ζ</span>., «evitar o dano, poupar-se de prejuízo», versículo 21. <span class=\"greek\">ἡγοῦμαί</span> <span class=\"greek\">τι</span> <span class=\"greek\">ζημίαν</span>, «considero alguma coisa uma perda» (Xenofonte, Mem. 2, 4, 3; cf. 2, 3, 2; Epicteto 2, 10, 15; 3, 26, 25 [oposto a <span class=\"greek\">κέρδος</span>, como em Lísias 7, 12; Platão, Leg. 835b e outros]), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.3.8\" target=\"_blank\" rel=\"noopener noreferrer\">Fp 3:8</a>; cf. versículo 7. — B. 809; DELG; M-M; TW; Spicq; Sv.</p></section></article>\n<article id=\"entry-zemioo-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ζημιόω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">Futuro, terceira pessoa do plural <span class=\"greek\">ζημιώσουσιν</span>, Dt 22:19; primeiro aoristo, terceira pessoa do singular <span class=\"greek\">ἐζημίωσεν</span>, 1Esd 1:34. Passiva: primeiro futuro <span class=\"greek\">ζημιωθήσομαι</span>; primeiro aoristo <span class=\"greek\">ἐζημιώθην</span>, subjuntivo <span class=\"greek\">ζημιωθῶ</span>, particípio <span class=\"greek\">ζημιωθείς</span> (Eurípides, Heródoto e outros; inscrições, papiros, LXX, Fílon, Josefo, Test12Patr). Em geral, «causar dano ou impor punição»; em nossa literatura, apenas na passiva.</p><p class=\"entry-text\">① <strong>Sofrer perda de alguma coisa</strong>, implicando dificuldade ou sofrimento: <strong>sofrer dano ou prejuízo, perder, ser privado de, padecer lesão</strong> (PFlor 142, 8, a respeito de uma venda, <span class=\"greek\">ὥστε</span> <span class=\"greek\">μήτε</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">πιπράσκοντα</span> <span class=\"greek\">ζημιοῦσθαι</span>; Pv 22:3). Com acusativo <span class=\"greek\">τὶ</span>, «sofrer perda no tocante a algo, perder alguma coisa» (Tucídides 3, 40, 3; Platão, Leg. 916e; Fílon, Spec. Leg. 3, 143, <span class=\"greek\">τ</span>. <span class=\"greek\">τιμήν</span>; Josefo, Ant. 11, 214; ver B-D-F §159, 2; Rob. 485): <span class=\"greek\">τὴν</span> <span class=\"greek\">ψυχήν</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.16.26\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 16:26</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.8.36\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 8:36</a>; cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.9.25\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 9:25</a>; 2Cl 6:2. <span class=\"greek\">ἐν</span> <span class=\"greek\">μηδενὶ</span> <span class=\"greek\">ζ</span>. <span class=\"greek\">ἔκ</span> <span class=\"greek\">τινος</span>, «não sofrer prejuízo algum por parte de alguém», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.7.9\" target=\"_blank\" rel=\"noopener noreferrer\">2Co 7:9</a>. Na passiva permissiva (Gildersleeve, <em>Syntax</em> I, §167), «permitir-se sofrer perda», com acusativo: <span class=\"greek\">δι</span>’ <span class=\"greek\">ὸ</span>̔<span class=\"greek\">ν</span> <span class=\"greek\">τὰ</span> <span class=\"greek\">πάντα</span> <span class=\"greek\">ἐζημιώθην</span>, «por causa de quem perdi todas as coisas», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.3.8\" target=\"_blank\" rel=\"noopener noreferrer\">Fp 3:8</a>.</p><p class=\"entry-text\">② <strong>Ser punido</strong> (Lísias 31, 26 e outros; OGI 669, 40; PTebt 5, 92; Pv 19:19; Josefo, Ant. 15, 16), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.3.15\" target=\"_blank\" rel=\"noopener noreferrer\">1Co 3:15</a>. — DELG, s.v. <span class=\"greek\">ζημία</span>; M-M; TW; Spicq.</p></section></article>\n<article id=\"entry-zenas-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Ζηνᾶς, acusativo -ᾶν, ὁ</h1><div class=\"entry-meta\"><span>nome próprio masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">(IMagnMai 323; Preisigke, <em>Namenbuch</em>). <strong>Zenas</strong>, cristão e <span class=\"greek\">νομικός</span> (ver esse verbete, acepção 2), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/TIT.3.13\" target=\"_blank\" rel=\"noopener noreferrer\">Tt 3:13</a>. — LGPN I; M-M.</p></section></article>\n<article id=\"entry-zenon-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Ζήνων, ωνος, ὁ</h1><div class=\"entry-meta\"><span>nome próprio masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">(Frequente na literatura, inclusive Josefo, inscrições e papiros; Taciano 3:1). <strong>Zenão</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TI.4.19\" target=\"_blank\" rel=\"noopener noreferrer\">2Tm 4:19</a>, variante de leitura; AcPl Ant 13, 5 (paralelo Aa I 236, 7, aqui como filho de Onesíforo e Lectra). — LGPN I.</p></section></article>\n<article id=\"entry-zeteo-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ζητέω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\"><strong><span class=\"greek\">ζητέω</span></strong>. Imperfeito <span class=\"greek\">ἐζήτουν</span>; futuro <span class=\"greek\">ζητήσω</span>; primeiro aoristo <span class=\"greek\">ἐζήτησα</span>. Passiva: imperfeito singular <span class=\"greek\">ἐζητεῖτο</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.8.7\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 8:7</a>; primeiro futuro <span class=\"greek\">ζητηθήσομαι</span>; aoristo <span class=\"greek\">ἐζητήθην</span> (LXX; AcPlCor 2:8; 1) (ver os dois verbetes seguintes; Homero e autores posteriores).</p><p class=\"entry-text\"><strong>① Procurar encontrar alguma coisa; buscar, procurar com o objetivo de encontrar</strong> (ver <span class=\"greek\">εὑρίσκω</span> 1a).</p><p class=\"entry-text\">ⓐ O que alguém possuía e perdeu: com acusativo <span class=\"greek\">τινά</span>, «alguém», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.28.5\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 28:5</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.1.37\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 1:37</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.2.48\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 2:48s</a>.; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.6.24\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 6:24</a>, 26; 7:34, 36. Com acusativo <span class=\"greek\">τί</span>, «alguma coisa», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.18.12\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 18:12</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.19.10\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 19:10</a>; AcPlCor 2:8 (ParJer 5:12). Em emprego absoluto, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.15.8\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 15:8</a>.</p><p class=\"entry-text\">ⓑ O que se deseja de algum modo trazer para uma relação consigo ou obter sem saber onde pode ser encontrado: com <span class=\"greek\">τινά</span>, «alguém», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TI.1.17\" target=\"_blank\" rel=\"noopener noreferrer\">2Tm 1:17</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.18.4\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 18:4</a>, 7s.; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.10.19\" target=\"_blank\" rel=\"noopener noreferrer\">At 10:19</a>, 21. <span class=\"greek\">ζητεῖν</span> <span class=\"greek\">τ</span>. <span class=\"greek\">θεόν</span>, <span class=\"greek\">εἰ</span> <span class=\"greek\">ἄρα</span> <span class=\"greek\">γε</span> <span class=\"greek\">αὐτὸν</span> <span class=\"greek\">εὕροιεν</span>, «buscar a Deus na esperança de talvez encontrá-lo», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.17.27\" target=\"_blank\" rel=\"noopener noreferrer\">At 17:27</a> (cf. Sb 1:1; 13:6; Fílon, Spec. Leg. 1, 36; Taciano 13, 2); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.10.20\" target=\"_blank\" rel=\"noopener noreferrer\">Rm 10:20</a> (Is 65:1). Com <span class=\"greek\">τί</span>, «alguma coisa», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.2.13\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 2:13</a>; 12:43; 13:45 (em sentido especial, «procurar comprar», como Xenofonte, Cyr. 2, 2, 26; Teofrasto, Char. 23, 8, <span class=\"greek\">ἱματισμὸν</span> <span class=\"greek\">ζητῆσαι</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">δύο</span> <span class=\"greek\">τάλαντα</span>); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.11.24\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 11:24</a>. <span class=\"greek\">τὶ</span> <span class=\"greek\">ἔν</span> <span class=\"greek\">τινι</span>, «alguma coisa em algo», como fruto em árvore, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.13.6\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 13:6s</a>. Em emprego absoluto, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.7.7\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 7:7s</a>.; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.11.9\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 11:9s</a>. (<span class=\"greek\">ζήτει</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">εὑρήσεις</span>, Epicteto 4, 1, 51).</p><p class=\"entry-text\">ⓒ Estar à procura: «procurar, buscar», com <span class=\"greek\">τινά</span>, «alguém», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.3.32\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 3:32</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.9.11\" target=\"_blank\" rel=\"noopener noreferrer\">At 9:11</a>; IPol 4:2. Com o objetivo de efetuar uma prisão, na passiva, GPt 7:26; MPol 3:2.</p><p class=\"entry-text\"><strong>② Buscar informação, investigar, examinar, considerar, deliberar</strong> (Xenofonte, Cyr. 8, 5, 13; Luciano, Hermot. 66; Eliano, VH 2, 13; 4Mc 1:13; Justino, D. 28, 1, <span class=\"greek\">τὸ</span> <span class=\"greek\">ζητούμενον</span>, «questão, problema»; cf. דרשׁ no hebraico e aramaico pós-bíblicos: Dalman, <em>Aram.-neuhebr. Handwörterbuch</em>² 1922; H. Strack, <em>Einleitg. in Talmud u. Midraš</em>⁵ 1921, 4). <span class=\"greek\">παραλόγως</span> <span class=\"greek\">ζ</span>., «dedicar-se a investigações irracionais», Dg 11:1. <span class=\"greek\">ἐν</span> <span class=\"greek\">ἑαυτῷ</span> <span class=\"greek\">ζ</span>. <span class=\"greek\">περί</span> <span class=\"greek\">τινος</span>, «ponderar alguma coisa consigo mesmo», Hs 2:1. <span class=\"greek\">περὶ</span> <span class=\"greek\">τούτου</span> <span class=\"greek\">ζητεῖτε</span> <span class=\"greek\">μετ</span>’ <span class=\"greek\">ἀλλήλων</span> <span class=\"greek\">ὅτι</span>;, «estais discutindo entre vós o fato de que...?», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.16.19\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 16:19</a> (Justino, D. 19, 1 e outros). Seguido de discurso indireto, «considerar» (Diodoro Sículo 1, 51, 6, <span class=\"greek\">πόσαι</span> …; Taciano 26, 1, <span class=\"greek\">τίς</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">θεός</span>; 29, 1, <span class=\"greek\">ὅτῳ</span> <span class=\"greek\">τρόπῳ</span>): <span class=\"greek\">πῶς</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.11.18\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 11:18</a>; 14:1, 11; <span class=\"greek\">τί</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.12.29\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 12:29</a>; <span class=\"greek\">τὸ</span> <span class=\"greek\">πῶς</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.22.2\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 22:2</a>; <span class=\"greek\">εἰ</span>, B 11:1. Como termo técnico jurídico, «investigar» (Dinarco 1, 8; POxy 237 VI, 41; 726, 16; O. Theb 134, 4; E. Bickermann, RHR 112, 1935, 214s.), <span class=\"greek\">ἔστιν</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">ζητῶν</span> <span class=\"greek\">κ</span>. <span class=\"greek\">κρίνων</span>, «há alguém que investiga e julga», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.8.50\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 8:50b</a> (cf. Fílon, De Jos. 174). <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.11.56\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 11:56</a> também pode ter esse sentido técnico.</p><p class=\"entry-text\"><strong>③ Empregar grande esforço para alcançar um desejo ou objetivo: esforçar-se por, visar a, tentar obter, desejar, querer.</strong></p><p class=\"entry-text\">ⓐ Desejar possuir algo, acusativo <span class=\"greek\">τὶ</span> (Luciano, Hermot. 66, <span class=\"greek\">τ</span>. <span class=\"greek\">εὐδαιμονίαν</span>; Justino, D. 102, 6, <span class=\"greek\">σωτηρίαν</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">βοήθειαν</span>). <span class=\"greek\">τ</span>. <span class=\"greek\">βασιλείαν</span>, «o Reino», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.6.33\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 6:33</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.12.31\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 12:31</a>; <span class=\"greek\">εὐκαιρίαν</span>, «oportunidade», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.26.16\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 26:16</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.22.6\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 22:6</a>; <span class=\"greek\">ψευδομαρτυρίαν</span>, «falso testemunho», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.26.59\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 26:59</a>; cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.14.55\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 14:55</a>; <span class=\"greek\">τὴν</span> <span class=\"greek\">δόξαν</span>, «a glória», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.5.44\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 5:44</a>; 7:18; 8:50a; <span class=\"greek\">τιμὴν</span> <span class=\"greek\">κ</span>. <span class=\"greek\">ἀφθαρσίαν</span>, «honra e incorruptibilidade», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.2.7\" target=\"_blank\" rel=\"noopener noreferrer\">Rm 2:7</a>; cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.7.27\" target=\"_blank\" rel=\"noopener noreferrer\">1Co 7:27b</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.12.14\" target=\"_blank\" rel=\"noopener noreferrer\">2Co 12:14</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/COL.3.1\" target=\"_blank\" rel=\"noopener noreferrer\">Cl 3:1</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.3.11\" target=\"_blank\" rel=\"noopener noreferrer\">1Pe 3:11</a> (Sl 33:15).</p><p class=\"entry-text\">ⓑ Desejar, ter por objetivo, com acusativo <span class=\"greek\">τὶ</span>: <span class=\"greek\">τὸν</span> <span class=\"greek\">θάνατον</span>, «a morte», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.9.6\" target=\"_blank\" rel=\"noopener noreferrer\">Ap 9:6</a>; <span class=\"greek\">λύσιν</span>, «libertação», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.7.27\" target=\"_blank\" rel=\"noopener noreferrer\">1Co 7:27a</a>; <span class=\"greek\">τὸ</span> <span class=\"greek\">θέλημά</span> <span class=\"greek\">τινος</span>, «a vontade de alguém», isto é, procurar satisfazê-la, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.5.30\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 5:30</a>; <span class=\"greek\">τὸ</span> <span class=\"greek\">σύμφορόν</span> <span class=\"greek\">τινος</span>, «o benefício de alguém» (Hermógenes 283, p. 301, 11 R., variante de leitura <span class=\"greek\">ἐμοῦ</span> … <span class=\"greek\">οὐ</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">Φιλίππου</span> <span class=\"greek\">συμφέρον</span> <span class=\"greek\">ζητοῦντος</span> [citação de Demóstenes 18, 30, que traz <span class=\"greek\">Φιλίππῳ</span>]), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.10.33\" target=\"_blank\" rel=\"noopener noreferrer\">1Co 10:33</a>; <span class=\"greek\">τὰ</span> (<span class=\"greek\">τὸ</span>) <span class=\"greek\">ἑαυτοῦ</span> <span class=\"greek\">ζητεῖν</span>, «procurar a própria vantagem», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.10.24\" target=\"_blank\" rel=\"noopener noreferrer\">1Co 10:24</a>; 13:5; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.2.21\" target=\"_blank\" rel=\"noopener noreferrer\">Fp 2:21</a>.</p><p class=\"entry-text\">ⓒ Com pronome interrogativo, <span class=\"greek\">τί</span> <span class=\"greek\">ζητεῖτε</span>;, «que quereis?» (cf. Gn 37:15), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.1.38\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 1:38</a>; cf. 4:27 (J. Foster, ET 52, 1940/41, 37s.).</p><p class=\"entry-text\">ⓓ Seguido de infinitivo (Heródoto 3, 137), geralmente aoristo (Plutarco, Thes. 35, 6; SIG 372, 7; Sb 8:2; Eclo 7:6; 27:1; Tb 5:14 BA; TestSol 15:7; Josefo, Ant. 11, 174; 13, 7): <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.12.46\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 12:46</a>; 21:46; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.12.12\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 12:12</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.5.18\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 5:18</a>; 9:9; 11:54, variante de leitura; 17:33; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.5.18\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 5:18</a>; 7:1; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.13.7\" target=\"_blank\" rel=\"noopener noreferrer\">At 13:7</a>, códice D, 8; 16:10 (cf. 3Km 11:22); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.10.3\" target=\"_blank\" rel=\"noopener noreferrer\">Rm 10:3</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.2.17\" target=\"_blank\" rel=\"noopener noreferrer\">Gl 2:17</a>. Raramente infinitivo presente (Xenofonte, An. 5, 4, 33; Est 8:12c), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.6.19\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 6:19</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.1.10\" target=\"_blank\" rel=\"noopener noreferrer\">Gl 1:10</a> (<span class=\"greek\">ζ</span>. <span class=\"greek\">ἀρέσκειν</span>, como Élio Aristides 34, 39 K. = 50, p. 560 D.). <span class=\"greek\">ἵνα</span> em lugar de infinitivo, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.14.12\" target=\"_blank\" rel=\"noopener noreferrer\">1Co 14:12</a>.</p><p class=\"entry-text\">ⓔ A linguagem do Antigo Testamento parece refletir-se em <span class=\"greek\">ζ</span>. <span class=\"greek\">τὴν</span> <span class=\"greek\">ψυχήν</span> <span class=\"greek\">τινος</span>, «procurar a vida de alguém», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.2.20\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 2:20</a> (cf. Êx 4:19); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.11.3\" target=\"_blank\" rel=\"noopener noreferrer\">Rm 11:3</a> (3Km 19:10); cf. também 3Km 19:14; Eclo 51:3; Sl 34:4; 37:13; 39:15; 53:5; 62:10; 85:14.</p><p class=\"entry-text\"><strong>④ Pedir, solicitar, exigir</strong>, com acusativo <span class=\"greek\">τὶ</span>, alguma coisa: <span class=\"greek\">σημεῖον</span>, «sinal», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.8.12\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 8:12</a>; <span class=\"greek\">σοφίαν</span>, «sabedoria», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.1.22\" target=\"_blank\" rel=\"noopener noreferrer\">1Co 1:22</a>; <span class=\"greek\">δοκιμήν</span>, «prova», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.13.3\" target=\"_blank\" rel=\"noopener noreferrer\">2Co 13:3</a>; <span class=\"greek\">τινά</span>, alguém, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.4.23\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 4:23</a>; <span class=\"greek\">τὶ</span> <span class=\"greek\">παρά</span> <span class=\"greek\">τινος</span>, «exigir algo de alguém» (Demóstenes 4, 33; Eclo 7:4; 28:3; 1Esd 8:50; Tb 4:18), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.8.11\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 8:11</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.11.16\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 11:16</a>; 12:48. Também <span class=\"greek\">τὶ</span> <span class=\"greek\">ἀπό</span> <span class=\"greek\">τινος</span>, B 21:6. <span class=\"greek\">ζητεῖται</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">τ</span>. <span class=\"greek\">οἰκονόμοις</span> <span class=\"greek\">ἵνα</span>, «exige-se dos administradores que...», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.4.2\" target=\"_blank\" rel=\"noopener noreferrer\">1Co 4:2</a> (A. Fridrichsen, ConNeot 7, 1942, 5). — B. 655; 764; DELG; M-M; EDNT; TW; Sv.</p></section></article>\n<article id=\"entry-zetema-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ζήτημα, ατος, τό</h1><div class=\"entry-meta\"><span>substantivo neutro</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">(Ver o verbete precedente; Sófocles, Hipócrates e autores posteriores; inscrições e papiros; Ez 36:37, variante de leitura; Justino, D. 123, 7; empréstimo no vocabulário rabínico). Em nossa literatura, somente em Atos, com o significado ainda conservado no grego moderno: <strong>questão [controvertida], assunto, argumento</strong> (Epicteto 2, 11, 8), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.15.2\" target=\"_blank\" rel=\"noopener noreferrer\">At 15:2</a>; 26:3. <span class=\"greek\">ζ</span>. <span class=\"greek\">περί</span> <span class=\"greek\">τινος</span>, «questões acerca de alguma coisa» (Platão, Leg. 10, 891c), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.18.15\" target=\"_blank\" rel=\"noopener noreferrer\">At 18:15</a>; 25:19. Em <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.23.29\" target=\"_blank\" rel=\"noopener noreferrer\">At 23:29</a>, como <span class=\"greek\">περί</span> já havia sido utilizado, o assunto da discussão é acrescentado no genitivo: <span class=\"greek\">ζ</span>. <span class=\"greek\">τοῦ</span> <span class=\"greek\">νόμου</span> <span class=\"greek\">αὐτῶν</span>. — DELG, s.v. <span class=\"greek\">ζητέω</span>; M-M.</p></section></article>\n<article id=\"entry-zetesis-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ζήτησις, εως, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">(Ver os dois verbetes precedentes; Sófocles, Heródoto e outros; inscrições, papiros, Fílon, Josefo; Justino; Melitão, HE 4, 26, 3).</p><p class=\"entry-text\">① <strong>Busca de informação, investigação</strong> (Platão e outros; Josefo, Vi. 302; especialmente como termo técnico jurídico: Dinarco 1, 10; OGI 629, 9; POxy 237 VIII, 39; 513, 45, <span class=\"greek\">ζ</span>. <span class=\"greek\">περὶ</span> <span class=\"greek\">τούτου</span>). <span class=\"greek\">ἀπορούμενος</span> <span class=\"greek\">ἐγὼ</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">περὶ</span> <span class=\"greek\">τούτων</span> <span class=\"greek\">ζ</span>., «porque eu estava perplexo quanto à investigação dessas coisas», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.25.20\" target=\"_blank\" rel=\"noopener noreferrer\">At 25:20</a>. Nas Epístolas Pastorais, pode denotar a investigação de problemas religiosos e teológicos (Alexandre de Afrodísias, Fat. 2, II 2, p. 166, 14, <span class=\"greek\">ζήτησις</span> <span class=\"greek\">περὶ</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">εἱμαρμένης</span>; cf. Fílon, Migr. Abr. 76; Justino, D. 1, 3): <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.6.4\" target=\"_blank\" rel=\"noopener noreferrer\">1Tm 6:4</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TI.2.23\" target=\"_blank\" rel=\"noopener noreferrer\">2Tm 2:23</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/TIT.3.9\" target=\"_blank\" rel=\"noopener noreferrer\">Tt 3:9</a>. Nesses contextos, porém, também são possíveis outras interpretações:</p><p class=\"entry-text\">② <strong>Matéria de disputa, questão controversa, controvérsia</strong> (Josefo, Ant. 15, 135; C. Ap. 1, 11), para <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TI.2.23\" target=\"_blank\" rel=\"noopener noreferrer\">2Tm 2:23</a> e <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/TIT.3.9\" target=\"_blank\" rel=\"noopener noreferrer\">Tt 3:9</a>.</p><p class=\"entry-text\">③ <strong>Participação em discussão controversa, debate, discussão, argumento</strong> (Diodoro Sículo 15, 48, 4; Justino, D. 68, 4; 80, 1), para <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.6.4\" target=\"_blank\" rel=\"noopener noreferrer\">1Tm 6:4</a> (com <span class=\"greek\">λογομαχία</span>); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.15.2\" target=\"_blank\" rel=\"noopener noreferrer\">At 15:2</a>, 7. <span class=\"greek\">ἐγένετο</span> <span class=\"greek\">ζ</span>. <span class=\"greek\">ἐκ</span> <span class=\"greek\">τ</span>. <span class=\"greek\">μαθητῶν</span> <span class=\"greek\">Ἰωάννου</span> <span class=\"greek\">μετὰ</span> <span class=\"greek\">Ἰουδαίου</span> <span class=\"greek\">περὶ</span> <span class=\"greek\">καθαρισμοῦ</span>, «surgiu uma discussão entre os discípulos de João e um judeu acerca da purificação», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.3.25\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 3:25</a> (cf. Heródoto 5, 21, <span class=\"greek\">ζ</span>. <span class=\"greek\">τῶν</span> <span class=\"greek\">ἀνδρῶν</span> <span class=\"greek\">τούτων</span> <span class=\"greek\">μεγάλη</span> <span class=\"greek\">ἐκ</span> <span class=\"greek\">τ</span>. <span class=\"greek\">Περσέων</span> <span class=\"greek\">ἐγίνετο</span>; Dionísio de Halicarnasso 8, 89, 4, <span class=\"greek\">ζ</span>. <span class=\"greek\">πολλὴ</span> <span class=\"greek\">ἐκ</span> <span class=\"greek\">πάντων</span> <span class=\"greek\">ἐγίνετο</span>; <span class=\"greek\">ζ</span>. <span class=\"greek\">περί</span> <span class=\"greek\">τινος</span>, como em Ateneu 3, 83a; Josefo, Ant. 14, 195; discussão entre cristãos e judeus, Orígenes, C. Cels. 3, 1, 16). — DELG, s.v. <span class=\"greek\">ζητέω</span>; M-M; TW; Sv. Nota editorial de abreviação: <span class=\"greek\">ζ</span>. representa aqui o lema deste artigo.</p></section></article>\n<article id=\"entry-zizanion-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ζιζάνιον, ου, τό</h1><div class=\"entry-meta\"><span>substantivo neutro</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">(ApcMos, capítulo 16; Geopon.; Etym. Mag., p. 411, 47). Provavelmente (Suda: <span class=\"greek\">ζιζάνιον</span>· <span class=\"greek\">ἡ</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">σίτῳ</span> <span class=\"greek\">αἶρα</span>) <strong>erva daninha nociva nos trigais, joio, cizânia</strong> (Geopon. 2, 43, <span class=\"greek\">τὸ</span> <span class=\"greek\">ζιζάνιον</span>, <span class=\"greek\">τὸ</span> <span class=\"greek\">λεγόμενον</span> <span class=\"greek\">αἶρα</span>, <span class=\"greek\">φθείρει</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">σῖτον</span>; sobre <span class=\"greek\">αἶρα</span>, sem <span class=\"greek\">ζ</span>., o mesmo se afirma em Teofrasto, HP 8, 8, 3; CP 4, 4, 8). Semelhante ao trigo, em nossa literatura ocorre apenas no plural (Geopon. 10, 87, 1; 14, 1, 5), em Mateus, na parábola das «ervas daninhas [joio] entre o trigo» (cf. também Pselo, p. 268, 17, <span class=\"greek\">οἱ</span> <span class=\"greek\">τὰ</span> <span class=\"greek\">ζιζάνια</span> <span class=\"greek\">ἐπισπείροντες</span>), Mt 13:25ss., 29s., 36, 38, 40 (ver R. Liechtenhan, <em>Kirchenblatt</em> 99, 1943, 146–49; 167–69). Supõe-se que a palavra tenha origem semítica: I. Löw, <em>Aramäische Pflanzennamen</em>, 1881, 133; H. Lewy, <em>D. semit. Fremdwörter im Griech.</em>, 1895, 52. Sobre o tema, ver L. Fonck, <em>Streifzüge durch die bibl. Flora</em>, 1900, 129s.; Sprenger, PJ 9, 1913, 89ss.; H. Guthe, ZDPV 41, 1918, 164s.; I. Löw, <em>D. Flora d. Juden</em> I, 1928, 723–29; A. Moldenke, <em>Plants of the Bible</em>, 1952; Zohary, <em>Plants</em>, 161. — DELG; M-M.</p></section></article>\n<article id=\"entry-zmyrna-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Ζμύρνα</h1><div class=\"entry-meta\"><span>nome próprio feminino; variante textual</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">(OGI 458, 41 [cerca de 9 a.C.]; PRyl 153, 18 [século II d.C.]; moedas de Esmirna desde o período de Trajano). Variante de leitura para <span class=\"greek\">Σμύρνα</span>, ver esse verbete. — M-M.</p></section></article>\n<article id=\"entry-zorobabel-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Ζοροβαβέλ, ὁ</h1><div class=\"entry-meta\"><span>nome próprio masculino indeclinável</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">Também -<span class=\"greek\">βάβελ</span> (זְרֻבָּבֶל), indeclinável (em Josefo, <span class=\"greek\">Ζοροβάβηλος</span>, <span class=\"greek\">ου</span>, Ant. 11, 95). <strong>Zorobabel</strong> (Zc 4:6, 9s.; Ag 1:1; 2:21, 23; 1Cr 3:19; 1Esd 4:13; 5:5, 8 e outros; 2Esd 2:2; 3:8; 17:7; Eclo 49:11; Vi Zech 3 [p. 88, 7 Sch.]), descendente de Davi, governador persa de Jerusalém após o retorno dos primeiros exilados (E. Sellin, <em>Serubbabel</em>, 1899); na genealogia de Jesus, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.1.12\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 1:12s</a>.; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.3.27\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 3:27</a>.</p></section></article>\n<article id=\"entry-zophos-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ζόφος, ου, ὁ</h1><div class=\"entry-meta\"><span>substantivo masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">(Homero, poetas trágicos e outros; Plutarco, Luciano; Epicteto, Fgm., p. 487, 2 Sch.; Símaco, Fílon; Atanásio, R. 19, p. 71, 30).</p><p class=\"entry-text\">① <strong>Escuridão que varia do estado parcial ao total, com sugestão de presságio sombrio; trevas, obscuridade</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.12.18\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 12:18</a>.</p><p class=\"entry-text\">② Especialmente <strong>escuridão das regiões inferiores, trevas</strong>, (Odisseia 20, 356) e também essas regiões (Ilíada 15, 191; 21, 56; Odisseia 11, 57). <span class=\"greek\">ὁ</span> <span class=\"greek\">ζόφος</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">σκότους</span>, «trevas negras» ou «as mais escuras regiões inferiores», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2PE.2.17\" target=\"_blank\" rel=\"noopener noreferrer\">2Pe 2:17</a>; Jd 13 (justaposição de <span class=\"greek\">ζ</span>. e <span class=\"greek\">σκότος</span> como em Élio Aristides 24, 44 K. = 44, p. 838 D.; Luciano, Catapl. 2). <span class=\"greek\">σειραὶ</span> <span class=\"greek\">ζόφου</span>, «cadeias do inferno», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2PE.2.4\" target=\"_blank\" rel=\"noopener noreferrer\">2Pe 2:4</a>. <span class=\"greek\">ὑπὸ</span> <span class=\"greek\">ζόφον</span>, «na escuridão» (literalmente «sob a escuridão»; cf. Ésquilo, Pers. 839; Eurípides, Hipp. 1416; Quinto de Esmirna 2, 619, <span class=\"greek\">ὑπὸ</span> <span class=\"greek\">ζ</span>., referente ao mundo inferior), Jd 6. Ver <span class=\"greek\">ταρταρόω</span>. — DELG; M-M; TW.</p></section></article>\n<article id=\"entry-zygos-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ζυγός, οῦ, ὁ</h1><div class=\"entry-meta\"><span>substantivo masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">(Hinos Homéricos, Cer. 217, e prosa desde Platão, Tim. 63b; Políbio, Epicteto; PFay 121, 4, <span class=\"greek\">εἰς</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">ζ</span>.; PStras 32, 12; LXX [Thackeray, p. 154]; En 103:11; PsSol 7:9 [acusativo sem artigo], 17:30; TestAbr A 12s. [Stone, p. 30, 6 e outros]; Justino, D. 53, 1; Atanásio, R. 58, 22 [? acusativo sem artigo]); em lugar do ático <span class=\"greek\">τὸ</span> <span class=\"greek\">ζυγόν</span> (Homero e outros; papiros; Gignac II 97; Josefo, Ant. 12, 194; Justino, D. 88, 8 [mas <span class=\"greek\">ζυγούς</span> em GThGk A 13, 1: Ea 152]).</p><p class=\"entry-text\">① <strong>Armação usada para controlar animais de trabalho ou, no caso de seres humanos, facilitar o transporte de cargas; jugo, canga</strong>. Em nossa literatura, apenas figuradamente, de qualquer fardo: <span class=\"greek\">ζ</span>. <span class=\"greek\">δουλείας</span>, «jugo de escravidão» (Sófocles, Aj. 944; cf. Heródoto 7, 8, <span class=\"greek\">γ</span> 3; Platão, Leg. 6, 770e; Demóstenes 18, 289; Gn 27:40), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.5.1\" target=\"_blank\" rel=\"noopener noreferrer\">Gl 5:1</a>. <span class=\"greek\">ὑπὸ</span> <span class=\"greek\">ζυγὸν</span> <span class=\"greek\">δοῦλοι</span>, «escravos sob o jugo» (isto é, da escravidão), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.6.1\" target=\"_blank\" rel=\"noopener noreferrer\">1Tm 6:1</a>. <span class=\"greek\">ζυγὸς</span> <span class=\"greek\">ἀνάγκης</span>, «jugo da necessidade» (Eurípides, Or. 1330), B 2:6. Sobre o ensino de Jesus, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.11.29\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 11:29s</a>. (cf. Eclo 51:26 e 6:24–28; T. Haering, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.11.28\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 11:28</a>–30, <em>A. Schlatter Festschrift</em>, 1922, 3–15; T. Arvedson, <em>D. Mysterium Christi</em>, 1937, 174–200; H. Betz, JBL 86, 1967, 10–24); D 6:2. <span class=\"greek\">ὑπὸ</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">ζυγὸν</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">χάριτος</span> <span class=\"greek\">ἔρχεσθαι</span>, «colocar-se sob o jugo da graça», 1Cl 16:17 (em contraste com ViDa 7 [p. 77, 12 Sch.], <span class=\"greek\">ὑπὸ</span> <span class=\"greek\">ζ</span>. <span class=\"greek\">γίνονται</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">Βελίαρ</span>). <span class=\"greek\">ἐπιθεῖναι</span> <span class=\"greek\">ζυγὸν</span> <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">τ</span>. <span class=\"greek\">τράχηλόν</span> <span class=\"greek\">τινος</span>, «pôr um jugo sobre o pescoço de alguém», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.15.10\" target=\"_blank\" rel=\"noopener noreferrer\">At 15:10</a> (expressões semelhantes tornaram-se fórmulas desde Hesíodo, Op. 815; Hinos Órficos 59, 5; Zósimo, Hist. 2, 37, 8; SibOr 3, 448). Desse significado, há breve transição para a aplicação de tal estrutura de equilíbrio a:</p><p class=\"entry-text\">② <strong>Instrumento para determinar peso; balança</strong>. O contexto de <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.6.5\" target=\"_blank\" rel=\"noopener noreferrer\">Ap 6:5</a> exige esse sentido, embora não se possa determinar definitivamente o gênero de <span class=\"greek\">ζ</span>. No grego mais antigo, a forma neutra, aparentemente preferida, <span class=\"greek\">τὸ</span> <span class=\"greek\">ζυγόν</span> refere-se à «barra da balança» (Ésquilo, Suppl. 822), depois à «balança, par de pratos» (Platão e outros; ver a LXX em Thackeray, op. cit.; Michel 1222, 4 [século II a.C.]; mas masculino em TestAbr A). — B. 726; DELG, s.v. <span class=\"greek\">ζεύγνυμι</span> III; Frisk, s.v. <span class=\"greek\">ζυγόν</span>; M-M; TW.</p></section></article>\n<article id=\"entry-zyme-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ζύμη, ης, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">(«Levedura, fermento», Aristóteles, Gen. An. 3, 4, 755a, 18ss.; Plutarco, Mor. 289f; PTebt 375, 27; LXX; Fílon, Spec. Leg. 1, 291; 2, 182; Josefo, Ant. 3, 252; Justino, D. 14, 3; cf. 14, 2 [<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.5.8\" target=\"_blank\" rel=\"noopener noreferrer\">1Co 5:8</a>?]).</p><p class=\"entry-text\">① <strong>Massa fermentada, fermento</strong> (a tradução «levedura» [como a NRSV geralmente e a REB em <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.13.33\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 13:33</a> e <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.13.21\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 13:21</a>] sugere popularmente um produto estranho à prática antiga de panificação), literalmente, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.13.33\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 13:33</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.13.21\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 13:21</a>. Mais completamente <span class=\"greek\">ζ</span>. <span class=\"greek\">τῶν</span> <span class=\"greek\">ἄρτων</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.16.12\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 16:12</a>. <span class=\"greek\">μικρὰ</span> <span class=\"greek\">ζύμη</span> <span class=\"greek\">ὅλον</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">φύραμα</span> <span class=\"greek\">ζυμοῖ</span>, «um pouco de fermento leveda toda a massa», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.5.6\" target=\"_blank\" rel=\"noopener noreferrer\">1Co 5:6</a> (Cyranides, p. 64, 22, <span class=\"greek\">μετὰ</span> <span class=\"greek\">ζύμης</span> <span class=\"greek\">μικρᾶς</span>) = <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.5.9\" target=\"_blank\" rel=\"noopener noreferrer\">Gl 5:9</a>. Essa expressão, por seu uso reiterado, mostra-se proverbial, e serve para ilustrar a influência de fatores aparentemente insignificantes no campo moral e religioso (sobre o aspecto negativo, H. Betz, <em>Galatians</em>, Hermeneia, 266, nota 125).</p><p class=\"entry-text\">② <strong>Aquilo que permeia negativamente a atitude ou comportamento, fermento</strong>, extensão figurada de ①: <span class=\"greek\">ζ</span>. é aplicado às atitudes dos fariseus e de Herodes, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.8.15\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 8:15</a>; à hipocrisia dos fariseus, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.12.1\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 12:1</a>; ao ensino dos fariseus e saduceus, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.16.6\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 16:6</a>, 11. Em IMg 10:2, o fermento envelhecido e azedo significa vida regulada pela instrução cultual judaica, em contraste com Jesus Cristo, a <span class=\"greek\">νέα</span> <span class=\"greek\">ζ</span>., «novo fermento», na mesma passagem. Usando linguagem das prescrições pascais (Êx 12:15, 19; 13:7; Dt 16:3s.), Paulo exorta: <span class=\"greek\">ἐκκαθάρατε</span> <span class=\"greek\">τ</span>. <span class=\"greek\">παλαιὰν</span> <span class=\"greek\">ζ</span>., «removei o fermento velho», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.5.7\" target=\"_blank\" rel=\"noopener noreferrer\">1Co 5:7</a>, e explica que o velho fermento é <span class=\"greek\">ζ</span>. <span class=\"greek\">κακίας</span> <span class=\"greek\">κ</span>. <span class=\"greek\">πονηρίας</span>, «fermento de malícia e maldade», versículo 8 (sobre problemas dessa imagem, Straub 80s.). — RAC I 1056–62; DELG; M-M; EDNT; TW.</p></section></article>\n<article id=\"entry-zymoo-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ζυμόω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">(Hipócrates e outros; Plutarco, Mor. 659b; LXX). <strong>Fermentar, levedar</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.5.6\" target=\"_blank\" rel=\"noopener noreferrer\">1Co 5:6</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.5.9\" target=\"_blank\" rel=\"noopener noreferrer\">Gl 5:9</a>. Na passiva (Fílon, Vi. Cont. 81), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.13.33\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 13:33</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.13.21\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 13:21</a>. — DELG, s.v. <span class=\"greek\">ζύμη</span>; TW.</p></section></article>\n<article id=\"entry-zo-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ζῶ</h1><div class=\"entry-meta\"><span>verbo remissivo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">Ver [<span class=\"greek\">ζάω</span>] <span class=\"greek\">ζῶ</span>.</p></section></article>\n<article id=\"entry-zogreo-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ζωγρέω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">(<span class=\"greek\">ζωός</span>, <span class=\"greek\">ἀγρέω</span>.) Futuro, segunda pessoa do plural <span class=\"greek\">ζωγρήσετε</span>, Dt 20:16; aoristo <span class=\"greek\">ἐζώγρησα</span>, LXX; particípio perfeito passivo <span class=\"greek\">ἐζωγρημένος</span> (Homero e outros; Kaibel 841, 7; LXX). <strong>Capturar vivo</strong> (Suda: <span class=\"greek\">ζωγρεῖ</span>· <span class=\"greek\">ζῶντας</span> <span class=\"greek\">λαμβάνει</span>; assim já em Homero; Heródoto 1, 86, 1; Xenofonte, An. 4, 7, 22; Políbio 3, 84, 10; Nm 31:18; 2Cr 25:12; Fílon, Virt. 43; Josefo, Bell. 2, 448, Ant. 9, 194; 20, 210; Taciano 18, 3). Figuradamente: <span class=\"greek\">ἀνθρώπους</span> <span class=\"greek\">ἔσῃ</span> <span class=\"greek\">ζωγρῶν</span>, «capturarás pessoas», isto é, ganhá-las para o Reino de Deus, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.5.10\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 5:10</a> (sobre a metáfora da pesca, cf. Aristeneto, Ep. 2, 23, <span class=\"greek\">ἀντὶ</span> <span class=\"greek\">ἰχθύων</span> <span class=\"greek\">παρθένους</span> <span class=\"greek\">ζ</span>.). <span class=\"greek\">ἐζωγρημένοι</span> <span class=\"greek\">ὑπ</span>’ <span class=\"greek\">αὐτοῦ</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">ἐκείνου</span> <span class=\"greek\">θέλημα</span>, «mantidos cativos por ele [o Diabo] para cumprir a vontade dele [do Diabo]» (ver B-D-F §291, 6; Rob. 707; sobre a ideia, cf. <em>Vi. Aesopi</em> W 106 P., <span class=\"greek\">εἱμαρμένη</span> <span class=\"greek\">ἐζώγρησεν</span>, «o destino [me] capturou para destruir [Esopo]»), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TI.2.26\" target=\"_blank\" rel=\"noopener noreferrer\">2Tm 2:26</a> (diferentemente L. Bunn, ET 41, 1930, 235–37). — DELG, s.v. <span class=\"greek\">ζωάγρια</span>; M-M; Spicq.</p></section></article>\n<article id=\"entry-zoe-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ζωή, ῆς, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\"><strong><span class=\"greek\">ζωή</span>, <span class=\"greek\">ῆς</span>, <span class=\"greek\">ἡ</span></strong> (Homero e autores posteriores; em Homero, «meios de vida» = «bens, propriedade», sem os quais não haveria vida; depois de Homero, «vida, existência», oposta à morte; posteriormente, «modo de vida», Heródoto 4, 112).</p><p class=\"entry-text\"><strong>① Vida no sentido físico; vida</strong> (<span class=\"greek\">ἐν</span> <span class=\"greek\">σαρκὶ</span> <span class=\"greek\">ζ</span>., Orígenes, C. Cels. 6, 59, 8).</p><p class=\"entry-text\">ⓐ Em contraste com <span class=\"greek\">θάνατος</span>, «morte» (Píndaro e outros; Luciano, Tox. 38; Eclo 37:18; Pv 18:21; Fílon; Justino, A I, 57, 3; Melitão, P. 49, 355), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.8.38\" target=\"_blank\" rel=\"noopener noreferrer\">Rm 8:38</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.3.22\" target=\"_blank\" rel=\"noopener noreferrer\">1Co 3:22</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.1.20\" target=\"_blank\" rel=\"noopener noreferrer\">Fp 1:20</a>. <span class=\"greek\">ἐν</span> <span class=\"greek\">τῇ</span> <span class=\"greek\">ζωῇ</span> <span class=\"greek\">σου</span>, «durante tua vida», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.16.25\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 16:25</a> (ver Eclo 30:5); cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.12.15\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 12:15</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.8.33\" target=\"_blank\" rel=\"noopener noreferrer\">At 8:33</a> (Is 53:8); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.4.14\" target=\"_blank\" rel=\"noopener noreferrer\">Tg 4:14</a>; 1Cl 16:8 (Is 53:8); 17:4 (cf. Jó 14:5); 20:10; Hm 3:3. <span class=\"greek\">πᾶς</span> <span class=\"greek\">χρόνος</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">ζωῆς</span> <span class=\"greek\">ἡμῶν</span>, «todo o tempo de nossa vida», B 4:9 (cf. PsSol 17:2; JosAs 13:12). <span class=\"greek\">πάσας</span> <span class=\"greek\">τὰς</span> <span class=\"greek\">ἡμέρας</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">ζωῆς</span> <span class=\"greek\">αὐτῶν</span>, «todos os dias de sua vida», Hs 9, 29, 2; cf. GJs 4:1; <span class=\"greek\">τὰς</span> <span class=\"greek\">λοιπὰς</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">ζωῆς</span> <span class=\"greek\">ἡμέρας</span>, «os dias restantes de vida», Hv 4, 2, 5; cf. Hv 5, 2; Hm 12, 2; Hs 6, 3, 6. <span class=\"greek\">τὴν</span> <span class=\"greek\">ἐσχάτην</span> <span class=\"greek\">ἡμέραν</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">ζωῆς</span> <span class=\"greek\">αὐτοῦ</span>, «o último dia de sua vida», Hv 3, 12, 2. <span class=\"greek\">ἐν</span> <span class=\"greek\">τῇ</span> <span class=\"greek\">ζ</span>. <span class=\"greek\">ταύτῃ</span>, «nesta vida», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.15.19\" target=\"_blank\" rel=\"noopener noreferrer\">1Co 15:19</a>; também <span class=\"greek\">ζ</span>. <span class=\"greek\">ἡ</span> <span class=\"greek\">νῦν</span>, «a vida presente» (em contraste com <span class=\"greek\">ἡ</span> <span class=\"greek\">μέλλουσα</span>, «a futura»), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.4.8\" target=\"_blank\" rel=\"noopener noreferrer\">1Tm 4:8</a> (Taciano 14, 2). <span class=\"greek\">τέλος</span> <span class=\"greek\">ζωῆς</span>, «fim da vida», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.7.3\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 7:3</a> (TestAbr A 1, p. 78, 5 [Stone, p. 4]). <span class=\"greek\">ζωὴ</span> <span class=\"greek\">κ</span>. <span class=\"greek\">πνοή</span>, «vida e respiração», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.17.25\" target=\"_blank\" rel=\"noopener noreferrer\">At 17:25</a> (cf. Gn 2:7; 7:22). <span class=\"greek\">πνεῦμα</span> <span class=\"greek\">ζωῆς</span>, «sopro de vida», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.11.11\" target=\"_blank\" rel=\"noopener noreferrer\">Ap 11:11</a> (cf. Gn 6:17; 7:15; TestAbr A 18, p. 100, 31 [Stone, p. 48]). <span class=\"greek\">ψυχὴ</span> <span class=\"greek\">ζωῆς</span>, «ser vivente», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.16.3\" target=\"_blank\" rel=\"noopener noreferrer\">Ap 16:3</a> (cf. Gn 1:30; Justino, D. 6, 1, <span class=\"greek\">ἡ</span> <span class=\"greek\">ψυχὴ</span> <span class=\"greek\">ἤτοι</span> <span class=\"greek\">ζωή</span> <span class=\"greek\">ἐστιν</span> <span class=\"greek\">ἢ</span> <span class=\"greek\">ζωὴν</span> <span class=\"greek\">ἔχει</span>). <span class=\"greek\">πρὸς</span> <span class=\"greek\">ζωῆς</span>, «necessário à vida», 1Cl 20:10. Da vida indestrutível dos que estão revestidos do corpo celestial, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.5.4\" target=\"_blank\" rel=\"noopener noreferrer\">2Co 5:4</a>. Também é desse caráter a vida do Cristo ressuscitado, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.5.10\" target=\"_blank\" rel=\"noopener noreferrer\">Rm 5:10</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.4.10\" target=\"_blank\" rel=\"noopener noreferrer\">2Co 4:10s</a>.; <span class=\"greek\">ζ</span>. <span class=\"greek\">ἀκατάλυτος</span>, «vida indestrutível», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.7.16\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 7:16</a>. <span class=\"greek\">ὁδοὶ</span> <span class=\"greek\">ζωῆς</span>, «caminhos de vida», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.2.28\" target=\"_blank\" rel=\"noopener noreferrer\">At 2:28</a> (Sl 15:11). Cristo é <span class=\"greek\">ἐν</span> <span class=\"greek\">θανάτῳ</span> <span class=\"greek\">ζ</span>. <span class=\"greek\">ἀληθινή</span>, «vida verdadeira na morte», IEph 7:2.</p><p class=\"entry-text\">ⓑ <strong>Meios de sustento, sustento</strong> (Heródoto e outros; Eclo 4:1; 29:21), Hs 9, 26, 2.</p><p class=\"entry-text\">ⓒ <strong>Curso ou modo de vida de alguém</strong> (cf. <span class=\"greek\">βίος</span> 1), Hm 8, 4 e 9; 11, 7 e 16; Hs 9, 16, 2 e outros. Em algumas dessas passagens, é perceptível uma transição para o aspecto moral.</p><p class=\"entry-text\"><strong>② Vida transcendente, vida.</strong></p><p class=\"entry-text\">ⓐ Deus e Cristo.</p><p class=\"entry-text\"><span class=\"greek\">α</span>. Deus como <span class=\"greek\">ζωή</span>, «vida», Dg 9:6b; como <span class=\"greek\">ζωὴ</span> <span class=\"greek\">αἰώνιος</span>, «vida eterna», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1JN.5.20\" target=\"_blank\" rel=\"noopener noreferrer\">1Jo 5:20</a>. Da cruz, IEph 18:1. É verdadeiro a respeito de Deus que <span class=\"greek\">ἔχει</span> <span class=\"greek\">ζωὴν</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">ἑαυτῷ</span>, «tem vida em si mesmo», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.5.26\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 5:26a</a>. O mandamento de Deus é vida eterna, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.12.50\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 12:50</a> (cf. Fílon, Fug. 198, Deus é a <span class=\"greek\">πρεσβυτάτη</span> <span class=\"greek\">πηγὴ</span> <span class=\"greek\">ζωῆς</span>, «a mais antiga fonte de vida»; Herm. Wr. 11, 13; 14; 12, 15, Deus é o <span class=\"greek\">πλήρωμα</span> <span class=\"greek\">τ</span>. <span class=\"greek\">ζωῆς</span>, «plenitude da vida»; PGM 3, 602 [ver Rtzst., Mysterienrel.³ 286, linha 11]; a divindade chamada <span class=\"greek\">Νοῦς</span>, «Intelecto», como <span class=\"greek\">ζωή</span> e <span class=\"greek\">φῶς</span>, «vida e luz», Herm. Wr. 1:9, 12, 17, 21, 32; 13:9, 18, 19; cf. ainda Sl 35:10; 55:14; SibOr Fgm. 3, 34; JosAs 8:10s. e outros).</p><p class=\"entry-text\"><span class=\"greek\">β</span>. De Cristo, que recebeu a vida de Deus, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.5.26\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 5:26b</a> (<span class=\"greek\">ἡ</span> <span class=\"greek\">ζωὴ</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">πίστεως</span>, «a vida da fé», ParJer 9:14). <span class=\"greek\">ἐν</span> <span class=\"greek\">αὐτῷ</span> <span class=\"greek\">ζ</span>. <span class=\"greek\">ἦν</span>, «nele estava a vida», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.1.4\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 1:4a</a>; cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1JN.5.11\" target=\"_blank\" rel=\"noopener noreferrer\">1Jo 5:11b</a>. Ele é o <span class=\"greek\">ἀρχηγὸς</span> <span class=\"greek\">τ</span>. <span class=\"greek\">ζωῆς</span>, «autor da vida», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.3.15\" target=\"_blank\" rel=\"noopener noreferrer\">At 3:15</a>; o <span class=\"greek\">λόγος</span> <span class=\"greek\">τ</span>. <span class=\"greek\">ζωῆς</span>, «Verbo da vida», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1JN.1.1\" target=\"_blank\" rel=\"noopener noreferrer\">1Jo 1:1</a>; cf. versículo 2; o <span class=\"greek\">ἄρτος</span> <span class=\"greek\">τ</span>. <span class=\"greek\">ζωῆς</span>, «pão da vida», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.6.35\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 6:35</a>, 48; cf. versículo 33 (E. Janot, <em>Le pain de vie</em>, Gregorianum 11, 1930, 161–70); também simplesmente <span class=\"greek\">ζωή</span>, «vida», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.11.25\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 11:25</a>; 14:6, ou <span class=\"greek\">ἡ</span> <span class=\"greek\">ζ</span>. <span class=\"greek\">ὑμῶν</span>, «vossa vida», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/COL.3.4\" target=\"_blank\" rel=\"noopener noreferrer\">Cl 3:4</a>; cf. B 2, 10; IMg 9:1. Como a vida que nele estava era <span class=\"greek\">τὸ</span> <span class=\"greek\">φῶς</span> <span class=\"greek\">τ</span>. <span class=\"greek\">ἀνθρώπων</span>, «a luz dos seres humanos», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.1.4\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 1:4b</a>, as pessoas, ao segui-lo, obtêm <span class=\"greek\">τὸ</span> <span class=\"greek\">φῶς</span> <span class=\"greek\">τ</span>. <span class=\"greek\">ζωῆς</span>, «a luz da vida», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.8.12\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 8:12</a> (sobre a combinação de luz e vida, cf. 1QS 3, 7 e os Hinos Órficos a Hélio, n.º 8, 18, Qu., <span class=\"greek\">ζωῆς</span> <span class=\"greek\">φῶς</span>; bem como inscrição cristã de Roma [Ramsay, <em>Luke the Physician</em>, 1908, p. 375, 238 d.C.], na qual um pai chama o filho falecido de <span class=\"greek\">γλυκύτερον</span> <span class=\"greek\">φωτὸς</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">ζοῆς</span>; ver também <span class=\"greek\">α</span> acima). — S. Bartina, «La vida como historia en J 1:1–18», Biblica 49, 1968, 91–96.</p><p class=\"entry-text\">ⓑ A discussão passa naturalmente à vida dos crentes, procedente de Deus e de Cristo.</p><p class=\"entry-text\"><span class=\"greek\">α</span>. Sem implicações escatológicas claras, vida de graça e santidade: <span class=\"greek\">ἐν</span> <span class=\"greek\">καινότητι</span> <span class=\"greek\">ζωῆς</span> <span class=\"greek\">περιπατεῖν</span>, «andar [isto é, viver] em novidade de vida», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.6.4\" target=\"_blank\" rel=\"noopener noreferrer\">Rm 6:4</a>; cf. IEph 19:3. <span class=\"greek\">ἀπηλλοτριωμένοι</span> <span class=\"greek\">τ</span>. <span class=\"greek\">ζωῆς</span> <span class=\"greek\">τ</span>. <span class=\"greek\">θεοῦ</span>, «alienados da vida de Deus», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.4.18\" target=\"_blank\" rel=\"noopener noreferrer\">Ef 4:18</a> (cf. Fílon, Post. Cai. 69, <span class=\"greek\">τῆς</span> <span class=\"greek\">θεοῦ</span> <span class=\"greek\">ζωῆς</span> <span class=\"greek\">ἀπεσχοινίσθαι</span>). <span class=\"greek\">ἡ</span> <span class=\"greek\">ζωὴ</span> <span class=\"greek\">τ</span>. <span class=\"greek\">ἀνθρώπων</span>, «a [verdadeira] vida das pessoas [em Deus]», Hm 2:1. — Da vida da salvação e da glória: é <span class=\"greek\">ζ</span>. <span class=\"greek\">κυρίου</span>, «vida do Senhor», B 1:4 (cf. PGM 12, 255, <span class=\"greek\">κύριε</span> <span class=\"greek\">τ</span>. <span class=\"greek\">ζωῆς</span>; 13, 783), ou <span class=\"greek\">ζ</span>. <span class=\"greek\">ἐν</span> <span class=\"greek\">Χρ</span>. <span class=\"greek\">Ἰησοῦ</span>, «vida em Cristo Jesus», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TI.1.1\" target=\"_blank\" rel=\"noopener noreferrer\">2Tm 1:1</a>; cf. <span class=\"greek\">ζωὴν</span> <span class=\"greek\">ὑμῖν</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">κύριος</span> <span class=\"greek\">χαρίζεται</span>, «o Senhor vos concede vida», Hs 9, 28, 6. Produzida pelas palavras de Cristo ou pela proclamação do evangelho: <span class=\"greek\">ῥήματα</span> <span class=\"greek\">ζ</span>. <span class=\"greek\">αἰωνίου</span>, «palavras de vida eterna», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.6.68\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 6:68</a>; cf. versículo 63. <span class=\"greek\">τὰ</span> <span class=\"greek\">ῥήματα</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">ζ</span>. <span class=\"greek\">ταύτης</span>, «as palavras desta vida», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.5.20\" target=\"_blank\" rel=\"noopener noreferrer\">At 5:20</a>. <span class=\"greek\">λόγος</span> <span class=\"greek\">ζωῆς</span>, «palavra da vida», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.2.16\" target=\"_blank\" rel=\"noopener noreferrer\">Fp 2:16</a>; cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TI.1.10\" target=\"_blank\" rel=\"noopener noreferrer\">2Tm 1:10</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.4.12\" target=\"_blank\" rel=\"noopener noreferrer\">2Co 4:12</a>. Assim, proclamando o evangelho, o apóstolo pode chamar-se portador do «aroma de Cristo» e conduzir os destinados a essa bem-aventurança, os salvos, <span class=\"greek\">ἐκ</span> <span class=\"greek\">ζωῆς</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">ζωήν</span>, «de vida para vida» (isto é, ao que parece, cada vez mais profundamente para dentro da vida divina), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.2.16\" target=\"_blank\" rel=\"noopener noreferrer\">2Co 2:16</a>. O Espírito, ao lado de Cristo, apresenta-se como poder da vida: <span class=\"greek\">πνεῦμα</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">ζωῆς</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">Χρ</span>. <span class=\"greek\">Ἰησοῦ</span>, «Espírito da vida em Cristo Jesus», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.8.2\" target=\"_blank\" rel=\"noopener noreferrer\">Rm 8:2</a>; cf. versículos 6, 10 e <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.6.63\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 6:63</a>. Tal como as palavras de Cristo, também o divino <span class=\"greek\">ἐντολή</span>, «mandamento», deve trazer vida, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.7.10\" target=\"_blank\" rel=\"noopener noreferrer\">Rm 7:10</a>; Hm 7:5; Hs 8, 7, 6. Essa <span class=\"greek\">ζ</span>. é considerada dom de Deus: <span class=\"greek\">ζ</span>. <span class=\"greek\">ἐν</span> <span class=\"greek\">ἀθανασίᾳ</span>, «vida em imortalidade», 1Cl 35:2. Com <span class=\"greek\">ἀφθαρσία</span>, «incorruptibilidade», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TI.1.10\" target=\"_blank\" rel=\"noopener noreferrer\">2Tm 1:10</a>; 2Cl 14:5; IPol 2:3. Com <span class=\"greek\">γνῶσις</span>, «conhecimento», D 9:3; Dg 12:3–7. Com <span class=\"greek\">εὐσέβεια</span>, «piedade», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2PE.1.3\" target=\"_blank\" rel=\"noopener noreferrer\">2Pe 1:3</a>; com <span class=\"greek\">εἰρήνη</span>, «paz», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.8.6\" target=\"_blank\" rel=\"noopener noreferrer\">Rm 8:6</a>; com <span class=\"greek\">σωτηρία</span>, «salvação», 2Cl 19:1. <span class=\"greek\">ἀγάπην</span> <span class=\"greek\">ἥτις</span> <span class=\"greek\">ἐστὶν</span> <span class=\"greek\">ἀρχὴ</span> <span class=\"greek\">ζωὴς</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">τέλος</span>, «amor, que é o princípio e o fim da vida», IEph 14:1. Os cristãos, verdadeiramente pertencentes à <span class=\"greek\">ἐκκλησία</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">ζωῆς</span>, «igreja da vida», 2Cl 14:1, são herdeiros da vida, dom da graça, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.3.7\" target=\"_blank\" rel=\"noopener noreferrer\">1Pe 3:7</a>. Essa vida, enquanto estão no corpo, <span class=\"greek\">κέκρυπται</span> <span class=\"greek\">σὺν</span> <span class=\"greek\">τ</span>. <span class=\"greek\">Χριστῷ</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">θεῷ</span>, «está escondida com Cristo em Deus», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/COL.3.3\" target=\"_blank\" rel=\"noopener noreferrer\">Cl 3:3</a>. Aqueles que perdem sua <span class=\"greek\">ζ</span>. (isto é, a vida real, em contraste com a existência física como <span class=\"greek\">ψυχή</span>) ficam excluídos da vida gloriosa, Hv 1, 1, 9; Hs 6, 2, 3; 8, 6, 4; 6; 8, 8, 2s.; 5; 9, 21, 4. Cf. também <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.11.18\" target=\"_blank\" rel=\"noopener noreferrer\">At 11:18</a> (ver 1QS 3, 1); 13:46, 48; <span class=\"greek\">ἡ</span> <span class=\"greek\">ὁδὸς</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">ζ</span>., «o caminho da vida», D 1:2; 4:14; <span class=\"greek\">τὰς</span> <span class=\"greek\">τρίβους</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">ζ</span>., «as veredas da vida», Hs 5, 6, 3. Especialmente no uso joanino, <span class=\"greek\">ζ</span>. é empregado abundantemente, em regra como resultado da fé em Cristo; na maior parte dos casos, afirma-se expressamente que o seguidor de Jesus possui vida já neste mundo: <span class=\"greek\">ἔχειν</span> <span class=\"greek\">ζωήν</span>, «ter vida» (Teofrasto em escólio a Platão 631c, <span class=\"greek\">εἰ</span> <span class=\"greek\">ζωὴν</span> <span class=\"greek\">εἶχεν</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">πλοῦτος</span>, «se a riqueza tivesse vida, estivesse viva»), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.3.15\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 3:15s</a>., 36a; 5:24a, 40; 6:40, 47, 51, 53s.; 10:10; 20:31; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1JN.3.15\" target=\"_blank\" rel=\"noopener noreferrer\">1Jo 3:15</a>; 5:12ab, 13. <span class=\"greek\">διδόναι</span> <span class=\"greek\">ζωήν</span>, «dar vida» (cf. Sb 8202, 3 [105 a.C.]), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.10.28\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 10:28</a>; 17:2; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1JN.5.11\" target=\"_blank\" rel=\"noopener noreferrer\">1Jo 5:11</a>; cf. 5:16. <span class=\"greek\">ὁρᾶν</span> <span class=\"greek\">ζωήν</span>, «ver vida», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.3.36\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 3:36b</a>. <span class=\"greek\">μεταβεβηκέναι</span> <span class=\"greek\">ἐκ</span> <span class=\"greek\">τ</span>. <span class=\"greek\">θανάτου</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">τ</span>. <span class=\"greek\">ζωήν</span>, «ter passado da morte para a vida», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.5.24\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 5:24</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1JN.3.14\" target=\"_blank\" rel=\"noopener noreferrer\">1Jo 3:14</a>. Assim, na passagem escatológica <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.5.29\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 5:29</a>, <span class=\"greek\">ἀνάστασις</span> <span class=\"greek\">ζωῆς</span> significa não a ressurreição para entrar na vida (cf. 2Mc 7:14; MPol 14:2, onde <span class=\"greek\">ἀνάστασις</span> <span class=\"greek\">ζωῆς</span> <span class=\"greek\">αἰ</span>., ao que parece, é ressurreição para a vida eterna), mas ressurreição correspondente à posse da vida pelo cristão já aqui e agora, uma ressurreição proveniente da vida. João gosta de chamar essa Vida <span class=\"greek\">ζ</span>. <span class=\"greek\">αἰώνιος</span>, «vida eterna», como em muitas passagens já citadas (ver <span class=\"greek\">αἰώνιος</span> 3): <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.3.15\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 3:15s</a>., 36; 4:14, 36; 5:24, 39; 6:27, 40, 47, 54, 68; 10:28; 12:25, 50; 17:2s.; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1JN.1.2\" target=\"_blank\" rel=\"noopener noreferrer\">1Jo 1:2</a>; 2:25; 3:15; 5:11, 13, 20. Mas o uso dessa expressão em nossa literatura de modo algum se limita a João e 1João; também ocorre em Mateus, Marcos, Lucas, Atos, Romanos, Gálatas, 1Timóteo, Tito, Judas, 2Clemente, Inácio, Martírio de Policarpo, Hermas e Didaquê (Justino, Melitão, Atanásio; Orígenes, C. Cels. 2, 77, 31 [com <span class=\"greek\">ἀνάστασις</span>]; cf. <span class=\"greek\">αἴδιος</span> <span class=\"greek\">ζ</span>., Taciano 14, 2), com conotação escatológica inequívoca.</p><p class=\"entry-text\"><span class=\"greek\">β</span>. <span class=\"greek\">ζ</span>. (e <span class=\"greek\">ζ</span>. <span class=\"greek\">αἰώνιος</span>; cf. 1QS 4:7; ver <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.3.15\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 3:15</a> e outros; oposto a <span class=\"greek\">ἀπώλεια</span>, TestAbr B 8, p. 113, 2 [Stone, p. 74]) é empregado para a vida no período bem-aventurado da consumação final nas passagens seguintes: <span class=\"greek\">ἐν</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">αἰῶνι</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">ἐρχομένῳ</span> <span class=\"greek\">ζ</span>. <span class=\"greek\">αἰ</span>., «no século vindouro, vida eterna», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.10.30\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 10:30</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.18.30\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 18:30</a>; cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.19.29\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 19:29</a> (Ar. 15, 3, <span class=\"greek\">ζ</span>. <span class=\"greek\">τοῦ</span> <span class=\"greek\">μέλλοντος</span> <span class=\"greek\">αἰώνος</span>). <span class=\"greek\">τί</span> <span class=\"greek\">ποιήσω</span> <span class=\"greek\">ἵνα</span> <span class=\"greek\">ζ</span>. <span class=\"greek\">αἰ</span>. <span class=\"greek\">κληρονομήσω</span>;, «que farei para herdar a vida eterna?», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.10.17\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 10:17</a>; cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.18.18\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 18:18</a>; 10:25; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.19.16\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 19:16s</a>. (PsSol 14:10). Como resultado do Juízo Final, <span class=\"greek\">ἀπελεύσονται</span> <span class=\"greek\">οἱ</span> <span class=\"greek\">δίκαιοι</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">ζ</span>. <span class=\"greek\">αἰ</span>., «os justos irão para a vida eterna», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.25.46\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 25:46</a> (cf. PsSol 13:11); ver também <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.2.7\" target=\"_blank\" rel=\"noopener noreferrer\">Rm 2:7</a> (cf. 1QS 4:6–8). Cf. ainda <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.7.14\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 7:14</a>; 18:8s.; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.9.43\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 9:43</a>, 45; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.5.17\" target=\"_blank\" rel=\"noopener noreferrer\">Rm 5:17s</a>., 21; 6:22s.; <span class=\"greek\">ζ</span>. <span class=\"greek\">ἐκ</span> <span class=\"greek\">νεκρῶν</span>, «vida para aqueles que saíram do estado de morte», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.11.15\" target=\"_blank\" rel=\"noopener noreferrer\">Rm 11:15</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.6.8\" target=\"_blank\" rel=\"noopener noreferrer\">Gl 6:8</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.1.16\" target=\"_blank\" rel=\"noopener noreferrer\">1Tm 1:16</a>; 6:12, 19; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.3.10\" target=\"_blank\" rel=\"noopener noreferrer\">1Pe 3:10</a> (Sl 33:13); Jd 21; 2Cl 8:4, 6; Dg 9:1, 6a. Sobre <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.5.4\" target=\"_blank\" rel=\"noopener noreferrer\">2Co 5:4</a>, ver 1a. Sobre mártires: <span class=\"greek\">τὴν</span> <span class=\"greek\">αἰώνιον</span> <span class=\"greek\">ζ</span>. <span class=\"greek\">ἐξαγοραζόμενοι</span>, «comprando para si a vida eterna», MPol 2:3 (códice Mosquense; outros códices gregos, <span class=\"greek\">κόλασιν</span>). Com <span class=\"greek\">ἀνάπαυσις</span> <span class=\"greek\">τ</span>. <span class=\"greek\">μελλούσης</span> <span class=\"greek\">βασιλείας</span>, «descanso do reino vindouro», 2Cl 5:5. Essa vida é chamada <span class=\"greek\">ἡ</span> <span class=\"greek\">ὄντως</span> <span class=\"greek\">ζ</span>., «vida real, verdadeira» (a redundância pode decorrer da consciência da distinção às vezes feita no mundo greco-romano entre a vida verdadeira <span class=\"greek\">ζωή</span> e a existência biológica <span class=\"greek\">βίος</span>; ver, por exemplo, IPriene 105, 10 = OGI 458, 10; cf. Cássio Díon 69, 19), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.6.19\" target=\"_blank\" rel=\"noopener noreferrer\">1Tm 6:19</a>; <span class=\"greek\">ζωῆς</span> <span class=\"greek\">ἀληθοῦς</span>, «vida verdadeira», Dg 12:4; <span class=\"greek\">ἡ</span> <span class=\"greek\">ἐπουράνιος</span> <span class=\"greek\">ζ</span>., «vida celestial», 2Cl 20:5; <span class=\"greek\">ἀί</span>̈<span class=\"greek\">διος</span> <span class=\"greek\">ζ</span>., «vida eterna», IEph 19:3 (ver <span class=\"greek\">ἀί</span>̈<span class=\"greek\">διος</span>). A esperança dirige-se a ela: <span class=\"greek\">ζωῆς</span> <span class=\"greek\">ἐλπίς</span>, «esperança de vida», B 1:6; cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/TIT.1.2\" target=\"_blank\" rel=\"noopener noreferrer\">Tt 1:2</a>; 3:7; Hs 9, 26, 2. Referências à glória futura incluem as seguintes expressões: <span class=\"greek\">βίβλος</span> ou <span class=\"greek\">βιβλίον</span> (<span class=\"greek\">τῆς</span>) <span class=\"greek\">ζωῆς</span>, «livro da vida» (ver <span class=\"greek\">βίβλος</span> 2), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.4.3\" target=\"_blank\" rel=\"noopener noreferrer\">Fp 4:3</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.3.5\" target=\"_blank\" rel=\"noopener noreferrer\">Ap 3:5</a>; 13:8; 17:8; 20:12, 15; 21:27; Hv 1, 3, 2. <span class=\"greek\">τὸ</span> <span class=\"greek\">ξύλον</span> (<span class=\"greek\">τῆς</span>) <span class=\"greek\">ζωῆς</span>, «árvore da vida» (4Mc 18:16; cf. Pv 3:18; Gn 2:9; PsSol 14:3; ParJer 9:16 [<span class=\"greek\">δένδρον</span>]; ApcEsdr 2:11; ApcMos 19 e outros; Fílon; ver <span class=\"greek\">ξύλον</span> 3), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.2.7\" target=\"_blank\" rel=\"noopener noreferrer\">Ap 2:7</a>; 22:2, 14, 19; Dg 12:3s. <span class=\"greek\">στέφανος</span> <span class=\"greek\">τ</span>. <span class=\"greek\">ζωῆς</span>, «coroa da vida» (ver Bousset, Rel.³ 277s.; M. Dibelius sobre <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.1.12\" target=\"_blank\" rel=\"noopener noreferrer\">Tg 1:12</a>; F. Cumont, <em>Études syriennes</em>, 1917, 63–69; ver <span class=\"greek\">στέφανος</span>), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.1.12\" target=\"_blank\" rel=\"noopener noreferrer\">Tg 1:12</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.2.10\" target=\"_blank\" rel=\"noopener noreferrer\">Ap 2:10</a>. <span class=\"greek\">ὕδωρ</span> (<span class=\"greek\">τῆς</span>) <span class=\"greek\">ζωῆς</span>, «água da vida» (Justino, D. 19, 2, <span class=\"greek\">βάπτισμα</span>; cf. <span class=\"greek\">ὕδωρ</span> 2), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.21.6\" target=\"_blank\" rel=\"noopener noreferrer\">Ap 21:6</a>; 22:1, 17. <span class=\"greek\">πηγὴ</span> <span class=\"greek\">ζωῆς</span>, «fonte da vida», B 11:2 (cf. Jr 2:13; Sl 35:10; OdeSol 11:6). <span class=\"greek\">ζωῆς</span> <span class=\"greek\">πηγαὶ</span> <span class=\"greek\">ὑδάτων</span>, «fontes de água viva», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.7.17\" target=\"_blank\" rel=\"noopener noreferrer\">Ap 7:17</a>. Sobre <span class=\"greek\">ἄρτος</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">ζωῆς</span>, ver <span class=\"greek\">ἄρτος</span> 2, ao final. — F. Burkitt, ZNW 12, 1911, 228–30; R. Charles, <em>A Critical History of the Doctrine of a Future Life in Israel, in Judaism and in Christianity</em>², 1913; F. Lindblom, <em>D. ewige Leben</em>, 1914; Bousset, Rel.³ 269–95; J. Frey, Biblica 13, 1932, 129–68; E. von Dobschütz, <em>D. Gewissheit des ew. Leb. nach d. NT</em>, em <em>Dienet einander</em> 29, 1920/21, 1–8; 43–52; 65–71; 97–101; J. Ubbink, <em>Het eeuwige leven bij Pls</em>, 1917; E. Sommerlath, <em>D. Ursprung d. neuen Lebens nach Pls</em>², 1926; J. Müller, <em>D. Lebensbegr. d. Hl. Pls</em>, 1940; N. von Arseniew, <em>D. neue Leben nach dem Eph.</em>, Internat. Kirchl. Ztschr. 20, 1930, 230–36; E. von Schrenk, <em>D. joh. Anschauung vom Leben</em>, 1898; J. Frey, «Vie dans l’Év. de St. Jean», Biblica 1, 1920, 37–58; 211–39; R. Bultmann, <em>D. Eschatol. d. Joh Ev.</em>, Zwischen d. Zeiten 6, 1928, 1ss.; H. Pribnow, <em>D. joh. Anschauung v. Leben</em>, 1934; D. Lyons, <em>The Concept of Eternal Life in J</em>, 1938; J. Koole, «Diorama Johanneum. <span class=\"greek\">Ζωή</span>», GereformTT 43, 1942, 276–84; F. Mussner, <em><span class=\"greek\">ΖΩΗ</span></em> (literatura joanina), dissertação, Munique, 1952; D. Hill, <em>Greek Words and Hebrew Meanings</em>, 1967, 163–201. — B. 285; ver <span class=\"greek\">βίος</span> e Schmidt, Syn. IV 40–53; DELG, s.v. <span class=\"greek\">ζώω</span> 1; EDNT; M-M; TW; Sv.</p></section></article>\n<article id=\"entry-zone-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ζώνη, ης, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">(Homero e outros; Kaibel 482, 3; papiros, LXX, EpArist, Fílon, Josefo, Test12Patr, JosAs; Melitão, Fgm. 8b 24, «zona», empréstimo rabínico). <strong>Cinto, cinturão</strong>; em nossa literatura, apenas de cinto de homem, exceto quando se refere a seres celestiais (Apocalipse). Sobre João Batista, <span class=\"greek\">ζ</span>. <span class=\"greek\">δερματίνη</span>, «cinto de couro» (4Km 1:8 = Josefo, Ant. 9, 22), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.3.4\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 3:4</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.1.6\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 1:6</a>; GEb 13, 79 (ver D. Buzy, <em>Pagne ou ceinture?</em>, RSR 23, 1933, 589–98, e sob <span class=\"greek\">Ἰωάννης</span> 1). Sobre Paulo, At 21:11ab. Sobre o Filho do Homem, <span class=\"greek\">περιεζωσμένος</span> <span class=\"greek\">πρὸς</span> <span class=\"greek\">τ</span>. <span class=\"greek\">μαστοῖς</span> <span class=\"greek\">ζ</span>. <span class=\"greek\">χρυσᾶν</span>, «cingido, à altura do peito, com cinturão de ouro», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.1.13\" target=\"_blank\" rel=\"noopener noreferrer\">Ap 1:13</a>; de modo semelhante sobre anjos, <span class=\"greek\">περιεζωσμένοι</span> <span class=\"greek\">περὶ</span> <span class=\"greek\">τὰ</span> <span class=\"greek\">στήθη</span> <span class=\"greek\">ζ</span>. <span class=\"greek\">χρυσᾶς</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.15.6\" target=\"_blank\" rel=\"noopener noreferrer\">Ap 15:6</a> (cf. 4Km 3:21, <span class=\"greek\">περιεζωσμένοι</span> <span class=\"greek\">ζ</span>.; cinto de ouro também em Pseudo-Calístenes 2, 21, 17). <span class=\"greek\">λύειν</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">ζ</span>., «soltar», isto é, retirar o cinto (Hipérides, Fgm. 67), MPol 13:2. Esse cinturão também serve para guardar dinheiro (Plutarco, Mor. 665b, <span class=\"greek\">ἀνθρώπου</span> … <span class=\"greek\">ζώνην</span> <span class=\"greek\">δὲ</span> <span class=\"greek\">χαλκοῦς</span> <span class=\"greek\">ἔχουσαν</span> <span class=\"greek\">ὑπεζωσμένου</span>; PRyl 127, 32 [29 d.C.], <span class=\"greek\">ζ</span>. <span class=\"greek\">ἐν</span> <span class=\"greek\">ᾗ</span> <span class=\"greek\">κέρματος</span> (<span class=\"greek\">δραχμαὶ</span>) <span class=\"greek\">δ</span>´; 141, 22), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.10.9\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 10:9</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.6.8\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 6:8</a>. — B. 434; DELG, s.v. <span class=\"greek\">ζώννυμι</span>; M-M; TW.</p></section></article>\n<article id=\"entry-zonnymi-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ζώννυμι</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">Variante <span class=\"greek\">ζωννύω</span>. Imperfeito, segunda pessoa do singular <span class=\"greek\">ἐζώννυες</span> (B-D-F §92; Mlt-H. 202s.); futuro <span class=\"greek\">ζώσω</span>; primeiro aoristo <span class=\"greek\">ἔζωσα</span>; primeiro aoristo médio, imperativo <span class=\"greek\">ζῶσαι</span>; particípio perfeito <span class=\"greek\">ἐζωσμένος</span>, LXX (Homero e outros; inscrições, LXX; TestJob 47:5; JosAs). <strong>Cingir alguém</strong>, com acusativo <span class=\"greek\">τινά</span>, Jo 21:18ab. Na voz média, «cingir-se» (Josefo, Bell. 2, 129), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.12.8\" target=\"_blank\" rel=\"noopener noreferrer\">At 12:8</a>. — DELG; TW.</p></section></article>\n<article id=\"entry-zoogoneo-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ζωογονέω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">(O texto de Nestle apresenta <span class=\"greek\">ζῳογ</span>-, mas o correto é <span class=\"greek\">ζωογ</span>-, do adjetivo <span class=\"greek\">ζωός</span>, «vivo», + <span class=\"greek\">γενέσθαι</span>; cf. <span class=\"greek\">ζωοποιέω</span> e B-D-F §26; distinto de <span class=\"greek\">ζῷον</span>, ver DELG, s.v. <span class=\"greek\">ζώω</span>). Futuro <span class=\"greek\">ζωογονήσω</span>; primeiro aoristo <span class=\"greek\">ἐζωογόνησα</span>, LXX; mais-que-perfeito, segunda pessoa do plural <span class=\"greek\">ἐζωοκονήκειτε</span>, Jz 8:19, variante de leitura (Aristóteles, Teofrasto e outros; Herm. Wr. 9, 6; LXX; JosAs 12:2, códice A [p. 12, 22 Bat.]; Fílon; Melitão, P. 101, 776, variante [em lugar de <span class=\"greek\">ἐζωοποίησα</span>, ver Ch.]).</p><p class=\"entry-text\">① <strong>Fazer viver, dar vida, vivificar</strong> (Teofrasto, CP 4, 15, 4; Ateneu 7, 298c; 1Km 2:6), com acusativo <span class=\"greek\">τὶ</span>, «alguma coisa» (ver Teofrasto e Ateneu, nos lugares citados), <span class=\"greek\">τὰ</span> <span class=\"greek\">πάντα</span>, «todas as coisas», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.6.13\" target=\"_blank\" rel=\"noopener noreferrer\">1Tm 6:13</a>.</p><p class=\"entry-text\">② <strong>Fazer permanecer vivo, manter ou preservar a vida</strong> (Diodoro Sículo 1, 23, 4; Êx 1:17s.; Jz 8:19; 1Km 27:9, 11; 3Km 21:31; Filópono, comentário sobre Aristóteles, An. p. 332, 9 Hayduck; Teófanes Confessor 337, 31; 379, 21 de Boor; Jorge Monge 166, 9 de B.). <span class=\"greek\">τὴν</span> <span class=\"greek\">ψυχήν</span>, «a vida», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.17.33\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 17:33</a>. Na passiva, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.7.19\" target=\"_blank\" rel=\"noopener noreferrer\">At 7:19</a>. — M-M; TW; Spicq.</p></section></article>\n"};
